21	static HcclResult GetHcclCommConfigVersion(const HcclCommConfig* config, uint32_t& version)
22	{
23	    CHK_PTR_NULL(config);
24	
25	    CommConfigInfo info{};
26	    s32 sRet = memcpy_s(&info, sizeof(info), config->reserved, sizeof(info));
27	    CHK_PRT_RET(sRet != EOK, HCCL_ERROR("[GetHcclCommConfigVersion] memcpy_s failed, errNo[%d]", sRet), HCCL_E_MEMORY);
28	    version = info.version;
29	    return HCCL_SUCCESS;
30	}
31	
32	static HcclResult ApplyHcclQos(const HcclCommConfig* hcclCommConfig, CommConfig& commConfig)
33	{
34	    if (hcclCommConfig == nullptr) {
35	        return HCCL_SUCCESS;
36	    }
37	
38	    // hcclQos 自 CommConfig version 10 起引入；低版本按未配置处理
39	    uint32_t configVersion = 0U;
40	    CHK_RET(GetHcclCommConfigVersion(hcclCommConfig, configVersion));
41	    if (configVersion < HCCL_COMM_CONFIG_QOS_VERSION) {
42	        HCCL_INFO(
43	            "[ApplyHcclQos] skip hcclQos by version, configVersion[%u] < HCCL_COMM_CONFIG_QOS_VERSION[%u]",
44	            configVersion, HCCL_COMM_CONFIG_QOS_VERSION);
45	        CHK_RET(commConfig.SetConfigHcclQos(HCCL_COMM_QOS_CONFIG_NOT_SET));
46	        return HCCL_SUCCESS;
47	    }
48	
49	    u32 qos = hcclCommConfig->hcclQos;
50	    CHK_PRT_RET(
51	        (qos != HCCL_COMM_QOS_CONFIG_NOT_SET) && (qos > 7u),
52	        HCCL_ERROR(
53	            "[ApplyHcclQos]errNo[0x%016llx] invalid hcclQos[%u], must be 0xFFFFFFFF or in [0,7]",
54	            HCCL_ERROR_CODE(HCCL_E_PARA), qos),
55	        HCCL_E_PARA);
56	    CHK_RET(commConfig.SetConfigHcclQos(qos));
57	    HCCL_INFO("[ApplyHcclQos] hcclQos[%u]", qos);
58	    return HCCL_SUCCESS;
59	}
60	
61	static HcclResult ApplyHcclSqDepth(const HcclCommConfig* hcclCommConfig, CommConfig& commConfig)
62	{
63	    if (hcclCommConfig == nullptr) {
64	        return HCCL_SUCCESS;
65	    }
66	
67	    uint32_t configVersion = 0U;
68	    CHK_RET(GetHcclCommConfigVersion(hcclCommConfig, configVersion));
69	    if (configVersion < HCCL_COMM_CONFIG_SQ_DEPTH_VERSION) {
70	        HCCL_INFO(
71	            "[ApplyHcclSqDepth] skip hcclSqDepth by version, configVersion[%u] < "
72	            "HCCL_COMM_CONFIG_SQ_DEPTH_VERSION[%u]",
73	            configVersion, HCCL_COMM_CONFIG_SQ_DEPTH_VERSION);
74	        return commConfig.SetConfigSqDepth(HCCL_COMM_SQ_DEPTH_CONFIG_NOT_SET);
75	    }
76	
77	    const uint32_t sqDepth = hcclCommConfig->hcclChannelSqDepth;
78	    CHK_RET(commConfig.SetConfigSqDepth(sqDepth));
79	    HCCL_INFO("[ApplyHcclSqDepth] hcclSqDepth[%u]", sqDepth);
80	    return HCCL_SUCCESS;
81	}
82	
83	static HcclResult ApplyTrafficClassAndServiceLevel(const HcclCommConfig* hcclCommConfig, CommConfig& commConfig)
84	{
85	    if (hcclCommConfig == nullptr) {
86	        return HCCL_SUCCESS;
87	    }
88	
89	    u32 tc = hcclCommConfig->hcclRdmaTrafficClass;
90	    CHK_PRT_RET(
91	        (tc != TC_DEFAULT) && (tc > TC_MAX || (tc % MULTIPLE != 0)),
92	        HCCL_ERROR(
93	            "[ApplyTrafficClassAndServiceLevel]errNo[0x%016llx] invalid hcclRdmaTrafficClass[%u], "
94	            "must be 0xFFFFFFFF or in [0,255] and a multiple of 4",
95	            HCCL_ERROR_CODE(HCCL_E_PARA), tc),
96	        HCCL_E_PARA);
97	    CHK_RET(commConfig.SetConfigTrafficClass(tc));
98	
99	    u32 sl = hcclCommConfig->hcclRdmaServiceLevel;
100	    CHK_PRT_RET(
101	        (sl != SL_DEFAULT) && (sl > SL_MAX),
102	        HCCL_ERROR(
103	            "[ApplyTrafficClassAndServiceLevel]errNo[0x%016llx] invalid hcclRdmaServiceLevel[%u], "
104	            "must be 0xFFFFFFFF or in [0,7]",
105	            HCCL_ERROR_CODE(HCCL_E_PARA), sl),
106	        HCCL_E_PARA);
107	    CHK_RET(commConfig.SetConfigServiceLevel(sl));
108	    return HCCL_SUCCESS;
109	}
110	
111	HcclResult ApplyHcclCommConfig(const HcclCommConfig* hcclCommConfig, CommConfig& commConfig, uint32_t& opExpansionMode)
112	{
113	    opExpansionMode = 0;
114	    if (hcclCommConfig == nullptr) {
115	        return HCCL_SUCCESS;
116	    }
117	
118	    opExpansionMode = hcclCommConfig->hcclOpExpansionMode;
119	    CHK_RET(ApplyTrafficClassAndServiceLevel(hcclCommConfig, commConfig));
120	    CHK_RET(ApplyHcclQos(hcclCommConfig, commConfig));
121	
122	    if (hcclCommConfig->hcclAlgo[0] != '\0') {
123	        size_t algoLen = strnlen(hcclCommConfig->hcclAlgo, static_cast<size_t>(HCCL_COMM_ALGO_MAX_LENGTH));
124	        CHK_RET(commConfig.SetConfigHcclAlgoStr(std::string(hcclCommConfig->hcclAlgo, algoLen)));
125	    }
126	    CHK_RET(ApplyHcclSqDepth(hcclCommConfig, commConfig));
127	    return HCCL_SUCCESS;
128	}
129	} // namespace hccl
