54	            cfg->sharedQueueTag = std::string(value);
55	            HCCL_INFO("[%s] set SHARED_QUEUE_TAG=%s.", __func__, cfg->sharedQueueTag.c_str());
56	            break;
57	        default:
58	            HCCL_ERROR("[%s] invalid str config type[%d].", __func__, static_cast<int>(type));
