11	#ifndef HCCL_COMM_CONFIG_PUB_H
12	#define HCCL_COMM_CONFIG_PUB_H
13	
14	#include "hccl_common.h"
15	#include "common.h"
16	
17	constexpr u32 COMM_CONFIG_MAGIC_WORD = 0xf0f0f0f0; // Magic word值，用于校验传入的配置结构体是否已经被初始化
18	constexpr uint32_t COMM_ALGO_MAX_LENGTH = 1600;        // hccl algo max length
19	constexpr uint32_t COMM_RETRY_ENABLE_MAX_LENGTH = 50;  // hccl_retry_enable max length
20	constexpr uint32_t COMM_RETRY_PARAMS_MAX_LENGTH = 128; // hccl_retry_params max length
21	constexpr int32_t COMM_EXECTIMEOUT_CONFIG_NOT_SET = 0xffffffff;
22	
23	enum CommConfigVersion {
24	    COMM_CONFIG_VERSION_ONE = 1,
25	    COMM_CONFIG_VERSION_TWO = 2,
26	    COMM_CONFIG_VERSION_THREE = 3,
27	    COMM_CONFIG_VERSION_FOUR = 4,
28	    COMM_CONFIG_VERSION_FIVE = 5,
29	    COMM_CONFIG_VERSION_SIX = 6,
30	    COMM_CONFIG_VERSION_SEVEN = 7,
31	    COMM_CONFIG_VERSION_EIGHT = 8,
32	    COMM_CONFIG_VERSION_NINE = 9,
33	    COMM_CONFIG_VERSION_TEN = 10,
34	    COMM_CONFIG_VERSION_ELEVEN = 11 // 当前支持的最高版本
35	};
36	
37	enum CommConfigOpExpansion {
38	    COMM_CONFIG_OPEXPANSION_DEFAULT = 0, // Config配置默认模式
39	    COMM_CONFIG_OPEXPANSION_HOST = 1,    // Config配置HOST模式
40	    COMM_CONFIG_OPEXPANSION_AICPU = 2,   // Config配置AICPU模式
41	    COMM_CONFIG_OPEXPANSION_AIV = 3,     // Config配置AIV模式
42	    COMM_CONFIG_OPEXPANSION_ONLY_AIV = 4 // Config配置only aiv模式
43	};
44	
45	// 通信域级别配置参数结构体 - 内部信息
46	using CommConfigInfo = struct CommConfigInfoDef {
47	    size_t configSize; // 配置结构体大小
48	    u32 magicWord;     // Magic word
49	    u32 version;       // HCCL版本
50	    char reserved[8];  // 8 byte 保留字段
51	};
52	
53	// 通信域级别配置参数结构体 - 外部配置项
54	using CommConfigHandle = struct CommConfigHandleDef {
55	    CommConfigInfo info;
56	    u32 bufferSize;                      // ccl buffer 大小配置
57	    u32 deterministic;                   // 确定性计算配置
58	    char commName[COMM_NAME_MAX_LENGTH]; // 通信域名称
59	    char udi[UDI_MAX_LENGTH];            // user define information
60	    u32 opExpansionMode;                 // 0：默认值  1：host  2：aicpu  3:aiv 4:aiv only
61	    u32 trafficClass;
62	    u32 serviceLevel;
63	    u32 worldRankID;
